# AIP-158 Pagination (page_token mờ, next_page_token rỗng là hết, trang ngắn chưa chắc là hết, token hết hạn); Paging 3.5.3 (overview,
# paged data, network + db); SubcomposeLayout.kt commit 3fa4054 (key trùng ném lỗi); Compose Lists (key ổn định, duy nhất). Đọc 2026-11-24.

SEC_ORDER = {'i7': ['hook', 'offset', 'cursor', 'token', 'paging3', 'bugs', 'ex']}


def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    a('preset.paging', 'Thiết kế hệ thống · phân trang danh sách tin', 'System design · paging the news list')
    m = lambda k, vi, en=None: a('m.paging.' + k, vi, en)
    m('title', 'Offset hay cursor khi danh sách đổi giữa lúc cuộn', 'Offset or cursor when the list changes mid-scroll')
    m('overview', 'Màn "Tin sức khỏe" của phòng khám hiện bài mới nhất trước, mỗi trang 4 bài. Trên server đang có bài 20 tới bài 9. Người dùng tải trang 1, đọc một lúc; trong lúc đó biên tập viên đăng bài 21 lên đầu, hay gỡ bài 18, hay làm cả hai. Rồi người dùng cuộn xuống tải trang 2. Ba cách: offset (bỏ qua bấy nhiêu mục đầu rồi lấy tiếp) khi có bài chèn; offset khi có bài bị gỡ; cursor (đánh dấu chỗ dừng bằng nội dung của mục cuối, qua một page_token) khi có cả hai.',
      'The clinic\'s "Health news" screen shows the newest post first, 4 posts per page. The server holds posts 20 down to 9. The user loads page 1 and reads for a while; meanwhile an editor publishes post 21 at the top, or removes post 18, or both. Then the user scrolls down to load page 2. Three ways: offset (skip that many items from the start, then take the next ones) with an insertion; offset with a removal; a cursor (marks where you stopped by the content of the last item, through a page_token) with both.')
    m('wrapup', 'Offset là vị trí trong danh sách tại thời điểm của từng request. Danh sách đổi giữa hai request thì vị trí trôi: chèn k bài phía trên thì k bài lặp, gỡ k bài thì k bài bị bỏ sót, và lỗi bỏ sót không để lại dấu vết nào. Cursor nói "tiếp sau bài 17" theo khóa sắp xếp, nên thay đổi phía trên không làm lệch trang sau. Cái giá: bài mới và bài đã gỡ chỉ hiện đúng sau lần làm mới.',
      'An offset is a position in the list as it was at each request. If the list changes between two requests, the positions drift: k posts inserted above give k duplicates, k posts removed give k skipped posts, and the skips leave no trace. A cursor says "continue after post 17" by the sort key, so changes above do not shift the next page. The price: new and removed posts only show correctly after a refresh.')
    m('simp.1', 'Số bài, cỡ trang 4, token "tk1", và việc thay đổi xảy ra đúng một lần giữa trang 1 và trang 2 là minh họa. App thật thường tải trang đầu lớn hơn và tải trước khi người dùng cuộn tới cuối.', 'The post numbers, the page size of 4, the token "tk1", and a single change between page 1 and page 2 are illustrative. Real apps usually load a larger first page and prefetch before the user reaches the end.')
    m('simp.2', 'Mô phỏng không có tải hai chiều (PREPEND, tải thêm cả phía trên), placeholder (ô giữ chỗ), tổng số mục, hay danh sách xếp theo độ liên quan (thứ tự tự đổi giữa các lần tìm). Phép đếm lặp và sót, câu SQL, số bài và token "tk1" là của site; Paging 3.5.3 là bản tài liệu được dùng.', 'The simulation leaves out two-way loading (PREPEND, loading above as well), placeholders, total counts and relevance-ranked lists (whose order shifts between searches). The duplicate and skip arithmetic, the SQL, the post numbers and the "tk1" token are the site\'s; Paging 3.5.3 is the documentation version used.')
    m('ctl.hint', 'Đổi cách phân trang rồi đi lại; so cột server và cột app ở bước 3.', 'Switch the paging approach and walk again; compare the server column with the app column at step 3.')
    m('ctl.case', 'Cách phân trang', 'Paging approach')
    for k, vi, en in [('offset', 'offset, có bài chèn lên đầu', 'offset, a post inserted at the top'), ('offsetdel', 'offset, có bài bị gỡ', 'offset, a post removed'), ('cursor', 'cursor (page_token), có cả hai', 'cursor (page_token), both changes')]:
        m('ctl.case.' + k, vi, en)
    m('diagramTitle', 'Màn tin, PagingSource, server, biên tập viên', 'News screen, PagingSource, server, editor')
    m('diagramDesc', 'Màn hình xin trang qua PagingSource (thành phần của thư viện Paging biết cách tải một trang); biên tập viên đổi danh sách trên server giữa hai lần xin', 'The screen asks for pages through the PagingSource (the Paging library component that knows how to load one page); the editor changes the server list between two requests')
    for k, vi, en in [('ui', 'Màn tin sức khỏe', 'Health news screen'), ('pager', 'PagingSource của app', 'The app\'s PagingSource'), ('server', 'Server tin', 'News server'), ('editor', 'Biên tập viên', 'Editor')]:
        m('n.' + k, vi, en)
    m('met.dup', 'Bài hiện lặp', 'Duplicated posts'); m('met.miss', 'Bài bị bỏ sót', 'Skipped posts'); m('met.gone', 'Bài đã gỡ còn trên màn hình', 'Removed posts still on screen')
    a('cap.paging', 'Màn hình bên trái xin trang qua PagingSource; biên tập viên bên phải đổi danh sách trên server.', 'The screen on the left asks for pages through the PagingSource; the editor on the right changes the server list.')
    S = [
        ('offset', 's1', 'Tải trang 1: offset=0, limit=4 → bài 20 tới 17', 'Load page 1: offset=0, limit=4 → posts 20 to 17', 'Khóa của trang là vị trí: trang 2 sẽ bắt đầu ở vị trí thứ 5 (offset=4). limit là số mục lấy mỗi lần.', 'The page key is a position: page 2 will start at the 5th position (offset=4). limit is how many items to take each time.'),
        ('offset', 's2', 'Bài 21 được đăng, chèn lên đầu', 'Post 21 is published at the top', 'Trên server, mọi bài cũ bị đẩy xuống một vị trí. App không biết gì.', 'On the server, every older post moves down one position. The app knows nothing.'),
        ('offset', 's3', 'Cuộn xuống: offset=4 → bài 17 tới 14', 'Scroll down: offset=4 → posts 17 to 14', 'Vị trí thứ 5 giờ là bài 17, bài đã nằm cuối trang 1. Bài 17 hiện hai lần.', 'The 5th position is now post 17, already the last post of page 1. Post 17 shows twice.'),
        ('offset', 's4', 'Danh sách có key = id: app crash', 'The list uses key = id: the app crashes', 'LazyColumn (danh sách cuộn của Compose) cần key (khóa định danh mỗi mục) duy nhất; hai mục cùng key 17 làm app crash. Không đặt key thì không crash, nhưng người dùng thấy bài lặp.', 'LazyColumn (Compose\'s scrolling list) needs unique keys (an identifier per item); two items with key 17 crash the app. Without keys it does not crash, but users see the duplicate.'),
        ('offsetdel', 's1', 'Tải trang 1: offset=0, limit=4 → bài 20 tới 17', 'Load page 1 with offset=0, limit=4 → posts 20 to 17', 'Giống cách trên; lần này danh sách sẽ ngắn đi thay vì dài ra.', 'As before; this time the list will shrink instead of grow.'),
        ('offsetdel', 's2', 'Bài 18 bị gỡ khỏi server', 'Post 18 is removed from the server', 'Mọi bài sau nó dồn lên một vị trí. App vẫn hiện bài 18 vì đã tải từ trước.', 'Every post after it moves up one position. The app still shows post 18 because it was loaded earlier.'),
        ('offsetdel', 's3', 'Cuộn xuống: offset=4 → bài 15 tới 12', 'Scroll down: offset=4 → posts 15 to 12', 'Vị trí thứ 5 giờ là bài 15. Bài 16 đã dồn lên vị trí thứ 4, mà app đã tải qua vị trí đó, nên bài 16 bị bỏ sót.', 'The 5th position is now post 15. Post 16 moved up to the 4th position, which the app has already passed, so post 16 is skipped.'),
        ('offsetdel', 's4', 'offset=8 → bài 11 tới 9, hết danh sách', 'offset=8 → posts 11 to 9, end of the list', 'Cuộn tới cuối vẫn không có bài 16, và không có gì báo lỗi. Lỗi bỏ sót khó phát hiện hơn lỗi lặp.', 'Scrolling to the end never shows post 16, and nothing reports an error. A skip is harder to notice than a duplicate.'),
        ('cursor', 's1', 'Tải trang 1: limit=4 → bài 20 tới 17, kèm next_page_token "tk1"', 'Load page 1: limit=4 → posts 20 to 17, with next_page_token "tk1"', 'next_page_token là chuỗi server cấp để đánh dấu chỗ tiếp theo. Nó chỉ vị trí theo nội dung, "sau bài 17", chứ không theo số lượng, "sau 4 bài". App không đọc token, chỉ gửi lại nguyên văn.', 'The next_page_token is a string the server hands out to mark the next spot. It marks a position by content, "after post 17", not by count, "after 4 posts". The app never reads the token; it sends it back unchanged.'),
        ('cursor', 's2', 'Bài 21 được đăng và bài 18 bị gỡ', 'Post 21 is published and post 18 is removed', 'Cả hai thay đổi cùng lúc, để xem cursor chịu được cả hai không.', 'Both changes at once, to see whether the cursor survives both.'),
        ('cursor', 's3', 'Cuộn xuống: gửi lại tk1 → bài 16 tới 13', 'Scroll down: send tk1 back → posts 16 to 13', 'Server trả các bài cũ hơn bài 17. Bài chèn hay bài gỡ ở phía trên không làm lệch. App chưa thấy bài 21, và bài 18 đã gỡ vẫn còn trên màn hình.', 'The server returns posts older than post 17. Insertions or removals above do not shift anything. The app has not seen post 21 yet, and the removed post 18 is still on screen.'),
        ('cursor', 's4', 'Kéo để làm mới: tải lại từ đầu → bài 21, 20, 19, 17…', 'Pull to refresh: reload from the top → posts 21, 20, 19, 17…', 'Làm mới thay cả danh sách: có bài 21, mất bài 18. Không lặp, không sót.', 'A refresh replaces the whole list: post 21 appears, post 18 goes. No duplicates, no skips.'),
    ]
    for case, k, tv, te, xv, xe in S:
        sid = case + '.' + k
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('try', 'Đi hết bốn bước của mỗi cách; ở bước 3 so cột server với cột app, tìm ô lặp và ô bị bỏ sót.', 'Walk all four steps of each approach; at step 3 compare the server column with the app column and look for duplicated and skipped cells.'),
        ('offset.s2', 'Zhiyong Tan nêu đúng tình huống này với trang ảnh thu nhỏ: người dùng đang ở trang 1 thì có ảnh mới chèn lên đầu; sang trang 2, mọi ảnh đã lệch đi một vị trí. [[src:book-acing]]', 'Zhiyong Tan describes exactly this with pages of thumbnails: the user is on page 1 when a new one is inserted at the front; on page 2, every thumbnail has shifted by one position. [[src:book-acing]]'),
        ('offset.s3', 'Chèn một bài phía trên thì một bài lặp; chèn ba bài thì ba bài lặp. Số bài lặp bằng số bài chèn phía trên chỗ đang tải. Đây là phép đếm của site.', 'One post inserted above gives one duplicate; three give three. The number of duplicates equals the number of posts inserted above the load point. This is the site\'s arithmetic.'),
        ('offset.s4', 'Tài liệu Compose khuyên key ổn định và duy nhất cho mỗi mục [[src:cp-lists]]. Mã SubcomposeLayout (cơ chế bố cục của Compose mà LazyColumn dùng để dựng từng mục; commit 3fa4054) kiểm tra điều đó: một key được dùng lần thứ hai thì ném lỗi "Key … was already used". [[src:ax-subcompose-src]]', 'The Compose docs recommend a stable, unique key per item [[src:cp-lists]]. The SubcomposeLayout code (the Compose layout mechanism LazyColumn uses to build each item; commit 3fa4054) checks it: a key used a second time throws "Key … was already used". [[src:ax-subcompose-src]]'),
        ('offsetdel.s2', 'Bài đã gỡ còn trên màn hình cho tới lần làm mới là chuyện của mọi cách phân trang. Cái nguy hiểm là ảnh hưởng của nó lên trang sau.', 'A removed post staying on screen until a refresh happens with every paging approach. The danger is what it does to the next page.'),
        ('offsetdel.s3', 'Gỡ một bài phía trên thì một bài bị nhảy qua. Khác lỗi lặp, ở đây không có gì hiện sai để người dùng nhận ra.', 'One post removed above means one post jumped over. Unlike a duplicate, nothing looks wrong for the user to notice.'),
        ('offsetdel.s4', 'Zhiyong Tan: đánh phiên bản cho phân trang (page_version, số phiên bản của danh sách gửi kèm mỗi request) chỉ đúng khi thêm hay xóa ở đầu danh sách; nên gửi mục cuối đang có thay vì số trang. [[src:book-acing]]', 'Zhiyong Tan: versioning the pagination (page_version, a version number of the list sent with each request) only works for additions or deletions at the start of the list; the recommendation is to pass the current last item instead of a page number. [[src:book-acing]]'),
        ('cursor.s2', 'AIP-158 (hướng dẫn thiết kế API của Google): token phải mờ (người dùng không đọc ra được cấu trúc bên trong) và an toàn để đưa vào URL. Nếu đọc được, người ta sẽ dựa vào cấu trúc bên trong và server không đổi cách phân trang được nữa. [[src:aip-158]]', 'AIP-158 (Google\'s API design guidance): tokens must be opaque (users cannot parse their internals) and safe to put in a URL. If they can be parsed, people will rely on their internals and the server can no longer change how it paginates. [[src:aip-158]]'),
        ('cursor.s3', 'Zhiyong Tan: lật tới thì gửi mục cuối hiện có (previous_last, "mục cuối của trang trước"), lật lui thì gửi mục đầu (previous_first, "mục đầu của trang trước"). Token tk1 làm đúng việc đó, gói trong một chuỗi mờ. [[src:book-acing]]', 'Zhiyong Tan: when flipping forward, pass the current last item (previous_last, "last item of the previous page"); backward, the first item (previous_first, "first item of the previous page"). The tk1 token does exactly that, wrapped in an opaque string. [[src:book-acing]]'),
        ('cursor.s4', 'Paging 3 (thư viện tải danh sách theo trang của Android): getRefreshKey cho khóa của lần làm mới; trả null là tải lại từ đầu. Dữ liệu dưới PagingSource đổi thì gọi invalidate() (báo "nguồn này đã cũ"), Pager (thành phần điều phối việc tải) tạo một PagingSource mới. [[src:ax-paging]]', 'Paging 3 (Android\'s page-loading library): getRefreshKey gives the key for a refresh; returning null reloads from the top. When the data under a PagingSource changes, call invalidate() (saying "this source is outdated") and the Pager (the component that drives loading) creates a new PagingSource. [[src:ax-paging]]')]:
        m('co.' + k, vi, en)

    z = lambda k, vi, en=None: a('vz.' + k, vi, en)
    z('tab.pg', 'Danh sách trên server và trong app', 'Server list and app list')
    z('pg.cap', 'Cột giữa là danh sách trên server lúc này, mới nhất ở trên; cột phải là những gì app đã tải, theo trang. Hai cột xếp theo cùng vị trí để thấy chỗ lệch.', 'The middle column is the server list right now, newest first; the right column is what the app has loaded, page by page. Both are lined up by position so the drift shows.')
    for k, vi, en in [('pos', 'Vị trí', 'Position'), ('srv', 'Server lúc này', 'Server now'), ('app', 'App đã tải', 'Loaded in the app'), ('page', 'Trang', 'Page')]:
        z('pg.col.' + k, vi, en)
    z('pg.post', 'bài {n}', 'post {n}')
    for k, vi, en in [('dup', 'lặp', 'duplicate'), ('gone', 'đã gỡ trên server', 'removed on the server'), ('miss', 'bị bỏ sót', 'skipped'), ('new', 'mới, chưa tải', 'new, not loaded')]:
        z('pg.mk.' + k, vi, en)
    for k, vi, en in [('p1', 'trang 1', 'page 1'), ('p2', 'trang 2', 'page 2'), ('p3', 'trang 3', 'page 3'), ('rf', 'làm mới', 'refresh')]:
        z('pg.page.' + k, vi, en)
    z('pg.reqh', 'Request của bước này', 'This step\'s request'); z('pg.evh', 'Thay đổi trên server', 'Change on the server')
    z('pg.req.none', 'Không gửi request mới.', 'No new request is sent.')
    z('pg.ev.ins', 'Bài 21 được đăng, chèn lên đầu.', 'Post 21 is published at the top.'); z('pg.ev.del', 'Bài 18 bị gỡ.', 'Post 18 is removed.')
    z('pg.crashh', 'App crash (LazyColumn có key = id)', 'The app crashes (LazyColumn with key = id)')
    z('pg.legend', 'Viền cam: trang vừa tải, hoặc bài mới chưa tải. Gạch đỏ: bài lặp hoặc bị bỏ sót. Chữ mờ: bài đã gỡ trên server nhưng còn trên màn hình.', 'Orange outline: the page just loaded, or a new post not loaded yet. Red hatched: a duplicated or skipped post. Faded: a post removed on the server but still on screen.')

    C = 'i7'
    a(C + '.title', 'Phân trang: offset và cursor', 'Paging: offset and cursor')
    a(C + '.essence', 'Offset là vị trí trong danh sách lúc request được gửi (bỏ qua bấy nhiêu mục đầu rồi lấy tiếp). Danh sách đổi giữa hai trang thì vị trí trôi: bài chèn phía trên thành bài lặp, bài gỡ phía trên làm một bài bị bỏ sót mà không ai thấy.\nCursor chỉ chỗ tiếp theo bằng nội dung của mục cuối, "sau bài 17" theo khóa sắp xếp (cách xếp thứ tự các mục, ví dụ theo giờ đăng), nên thay đổi phía trên không làm lệch trang sau.\nToken là chuỗi do server cấp để đánh dấu chỗ tiếp theo, và nên mờ (app không đọc được bên trong): app gửi lại nguyên văn, coi token rỗng là hết danh sách, và làm mới khi cần thấy bài mới hay bỏ bài đã gỡ.',
      'An offset is a position in the list when the request is sent (skip that many items from the start, then take the next ones). If the list changes between two pages, positions drift: a post inserted above becomes a duplicate, a post removed above makes another post vanish unnoticed.\nA cursor marks the next spot by the content of the last item, "after post 17" by the sort key (the way items are ordered, for example by publish time), so changes above do not shift the next page.\nA token is a string the server hands out to mark the next spot, and should be opaque (the app cannot read its inside): the app sends it back unchanged, treats an empty token as the end, and refreshes to see new posts or drop removed ones.')
    a(C + '.goal.g1', 'Đã thấy trang 2 sau khi danh sách đổi', 'Saw page 2 after the list changed')
    a(C + '.goal.g2', 'Đã thấy kết cục của cách phân trang', 'Saw how the paging approach ends up')
    a(C + '.sim.sysdesign.paging', 'offset khi có bài chèn, offset khi có bài gỡ, cursor', 'offset with an insertion, offset with a removal, cursor')

    S_ = 'hook'
    a(C + '.sec.%s.title' % S_, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'predict', 'Màn tin gọi GET /news?page=2&size=20. Một người đang đọc trang 1 thì có 3 bài mới được đăng. Họ cuộn xuống. Họ thấy gì ở đầu trang 2? Nếu thay vào đó có 3 bài bị gỡ thì sao?',
      'The news screen calls GET /news?page=2&size=20. While someone reads page 1, 3 new posts are published. They scroll down. What do they see at the top of page 2? What if 3 posts had been removed instead?')
    B(C, S_, 1, 'ans', 'Ba bài cuối của trang 1 hiện lại ở đầu trang 2, vì mọi bài bị đẩy xuống ba vị trí. Nếu gỡ ba bài thì ba bài đầu của trang 2 cũ dồn lên trang 1 (đã tải xong) và bị bỏ qua, mà không có gì báo lỗi. [[src:book-acing]]',
      'The last three posts of page 1 show again at the top of page 2, because everything moved down three positions. If three posts were removed, the first three posts of the old page 2 move up into page 1 (already loaded) and are skipped, with no error anywhere. [[src:book-acing]]')

    S_ = 'offset'
    a(C + '.sec.%s.title' % S_, 'Offset: khóa là vị trí', 'Offset: the key is a position')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Phân trang offset gửi "bỏ qua N mục, lấy M mục": offset=40&limit=20, hay page=3&size=20 (tức offset 40). Dễ làm, nhảy thẳng tới trang bất kỳ được. Nhưng N là vị trí trong danh sách tại thời điểm của request đó, không phải của request trước. Zhiyong Tan chỉ ra hệ quả với trang ảnh thu nhỏ: có ảnh mới ở đầu khi người dùng đang ở trang 1 thì trang 2 trả về lệch một ảnh. [[src:book-acing]]',
      'Offset paging sends "skip N items, take M": offset=40&limit=20, or page=3&size=20 (offset 40). It is easy and allows jumping to any page. But N is a position in the list at the time of that request, not the previous one. Zhiyong Tan shows the consequence with pages of thumbnails: a new thumbnail at the front while the user is on page 1 makes page 2 come back shifted by one. [[src:book-acing]]')
    B(C, S_, 2, 'p', 'Phép đếm của site: chèn k mục phía trên chỗ đang tải thì k mục cuối đã thấy hiện lại; gỡ k mục phía trên thì k mục chưa thấy bị nhảy qua. Lỗi lặp còn lọc được ở app theo id; lỗi bỏ sót thì không, vì app không bao giờ nhận được mục đó.',
      'The site\'s arithmetic: k items inserted above the load point make the last k seen items show again; k items removed above make k unseen items get jumped over. Duplicates can still be filtered in the app by id; skips cannot, because the app never receives those items.')
    B(C, S_, 3, 'note', 'Zhiyong Tan có nêu một cách vá: đánh phiên bản cho phân trang (gắn một số phiên bản của danh sách), GET /news?page=2&page_version=…, để các trang sau dùng cùng một bản của danh sách. Cũng theo đó, cách này chỉ đúng khi thêm hay xóa ở đầu danh sách; thay đổi ở giữa thì người dùng không thấy mục mới, hoặc vẫn thấy mục đã xóa. [[src:book-acing]]',
      'Zhiyong Tan mentions one patch: version the pagination (attach a version number of the list), GET /news?page=2&page_version=…, so later pages use the same version of the list. The same source adds that this only works for additions or deletions at the start; changes in the middle mean users miss new items or keep seeing deleted ones. [[src:book-acing]]')
    B(C, S_, 3, 'kind', 'pitfall')

    S_ = 'cursor'
    a(C + '.sec.%s.title' % S_, 'Cursor: khóa là nội dung', 'Cursor: the key is content')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Cách Zhiyong Tan gọi là tốt hơn: client (ở đây là app) gửi mục cuối hiện có khi lật tới (previous_last) và mục đầu khi lật lui (previous_first). Server trả "các mục sau mục này" thay vì "các mục từ vị trí N". Chèn hay gỡ phía trên không đổi được câu trả lời đó. [[src:book-acing]]',
      'What Zhiyong Tan calls the better technique: the client (here, the app) passes the current last item when flipping forward (previous_last) and the first item when flipping back (previous_first). The server returns "the items after this one" instead of "the items from position N". Insertions or removals above cannot change that answer. [[src:book-acing]]')
    B(C, S_, 2, 'p', 'Diễn giải của site về cách server làm: sắp theo một khóa có thứ tự toàn phần (mọi cặp mục đều so sánh được, không cặp nào ngang nhau), như (giờ đăng, id), với id làm khóa phân xử (tie-breaker) cho hai bài cùng giờ. Cursor mang cặp giá trị của mục cuối; trang sau là các bài có cặp nhỏ hơn. Vì so sánh theo giá trị, cách này vẫn đúng khi chính bài 17 bị gỡ: không cần bài 17 còn tồn tại.',
      'The site\'s reading of the server side: sort by a key with a total order (any two items can be compared, and no two tie), such as (published time, id), with the id as tie-breaker between posts published at the same moment. The cursor carries the last item\'s pair; the next page is the posts with a smaller pair. Because it compares values, it still works when post 17 itself is removed: post 17 does not need to exist.')
    B(C, S_, 3, 'kt', 'SELECT * FROM posts\nWHERE (published_at, id) < (:t17, 17)        -- giải từ page_token\nORDER BY published_at DESC, id DESC\nLIMIT 4',
      'SELECT * FROM posts\nWHERE (published_at, id) < (:t17, 17)        -- decoded from page_token\nORDER BY published_at DESC, id DESC\nLIMIT 4')
    B(C, S_, 4, 'note', 'Cái giá của cursor: không nhảy thẳng tới "trang 37", không có sẵn "trang 3 trên 12", và bài mới phía trên chỉ hiện sau khi làm mới. Với feed cuộn vô hạn thì không sao. Với bảng quản trị cần số trang và dữ liệu ít đổi, offset vẫn chấp nhận được. Đây là nhận xét của site.',
      'The cursor\'s price: no jumping straight to "page 37", no built-in "page 3 of 12", and new posts above only appear after a refresh. For an endless feed that is fine. For an admin table that needs page numbers over data that rarely changes, offset is still acceptable. This is the site\'s observation.')

    S_ = 'token'
    a(C + '.sec.%s.title' % S_, 'Token mờ theo AIP-158', 'Opaque tokens per AIP-158')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'AIP-158 (hướng dẫn thiết kế API của Google): request có page_size và page_token, response có next_page_token. Token phải mờ: an toàn cho URL, người dùng không đọc ra được; mã hóa Base64 (cách đổi dữ liệu thành chữ, ai cũng giải ngược được) một cấu trúc rõ ràng không đủ. Lý do: đọc được thì người ta sẽ dựa vào nó, và cách phân trang bên trong thành một phần của API, không đổi được nữa. Token chỉ nói chỗ tiếp tục, không cấp quyền; mỗi request vẫn phải kiểm tra quyền. [[src:aip-158]]',
      'AIP-158 (Google\'s API design guidance): the request has page_size and page_token, the response has next_page_token. Tokens must be opaque: URL-safe and not user-parseable; Base64 (a way of turning data into text that anyone can decode) of a readable structure is not enough. The reason: if people can parse them they will rely on them, and the pagination internals become part of the API that can no longer change. A token only says where to continue and grants no access; every request is still authorised. [[src:aip-158]]')
    B(C, S_, 2, 'p', 'Ba quy tắc app cần theo, cũng từ AIP-158. next_page_token rỗng là cách duy nhất báo hết danh sách. Một trang có thể ít hơn page_size, kể cả không có mục nào, mà chưa hết, nên đừng dừng vì trang ngắn. Giữa các trang chỉ được đổi page_size; đổi tham số khác (bộ lọc, thứ tự) thì server nên báo INVALID_ARGUMENT (mã lỗi "tham số không hợp lệ"), nên đổi bộ lọc là bắt đầu lại từ đầu. Token có thể hết hạn, thường khoảng ba ngày; gặp lỗi đó thì làm mới. [[src:aip-158]]',
      'Three rules for the app, also from AIP-158. An empty next_page_token is the only end-of-list signal. A page may hold fewer than page_size results, even none, before the end, so do not stop on a short page. Only page_size may change between pages; changing anything else (filters, order) should get INVALID_ARGUMENT (the error code for "invalid argument"), so a new filter means starting over. Tokens may expire, about three days as a rule of thumb; on that error, refresh. [[src:aip-158]]')
    B(C, S_, 3, 'note', 'AIP-158 cũng nói thêm phân trang vào một API đã có là thay đổi không tương thích, nên phải có từ đầu. Site rút ra: đó là một câu hỏi nên đặt cho backend ngay ở bước lập kế hoạch (chương I1, "Từ đề bài tới kế hoạch"). [[src:aip-158]]',
      'AIP-158 also says adding pagination to an existing API is a breaking change, so it has to be there from the start. The site\'s takeaway: that is a question to put to the backend at the planning stage (chapter I1, "From a brief to a plan"). [[src:aip-158]]')
    B(C, S_, 3, 'kind', 'source')

    S_ = 'paging3'
    a(C + '.sec.%s.title' % S_, 'Paging 3 trên Android', 'Paging 3 on Android')
    a(C + '.sec.%s.badge' % S_, 'version')
    B(C, S_, 1, 'p', 'Thư viện Paging (bản 3.5.3 trong tài liệu) là thư viện Android chuyên tải danh sách theo trang, và chia việc theo tầng: PagingSource ở tầng repository (lớp lấy dữ liệu cho app) biết cách tải một trang; Pager ở ViewModel (lớp giữ dữ liệu cho màn hình) tạo dòng PagingData; UI Compose gọi collectAsLazyPagingItems() để đổi dòng đó thành danh sách cho LazyColumn. Thư viện tự cache các trang đã tải trong RAM, gộp request trùng, và có sẵn làm mới, thử lại. load() trả LoadResult.Page(data, prevKey, nextKey), với null nghĩa là hết theo chiều đó, hoặc LoadResult.Error khi lỗi mạng. [[src:ax-paging]]',
      'The Paging library (3.5.3 in the docs) is Android\'s library for loading lists page by page, and splits the work by layer: a PagingSource in the repository layer (the layer that gets data for the app) knows how to load one page; a Pager in the ViewModel (the layer that holds data for the screen) builds a PagingData stream; Compose UI calls collectAsLazyPagingItems() to turn that stream into a list for LazyColumn. The library caches loaded pages in memory, deduplicates requests, and has refresh and retry built in. load() returns LoadResult.Page(data, prevKey, nextKey), with null meaning nothing more in that direction, or LoadResult.Error on a network failure. [[src:ax-paging]]')
    B(C, S_, 2, 'p', 'Khóa của PagingSource là kiểu bạn chọn: Int cho offset hay số trang, String cho page_token. Thư viện không chọn hộ cách phân trang: PagingSource<Int, …> với offset vẫn lặp và sót như mô phỏng. Tài liệu coi nguồn dữ liệu là bất biến (không đổi sau khi tạo): dữ liệu bên dưới đổi thì gọi invalidate(), Pager tạo PagingSource mới và tải lại từ khóa getRefreshKey() trả về. [[src:ax-paging]]',
      'A PagingSource key is whatever type you pick: Int for an offset or page number, String for a page_token. The library does not pick the paging scheme for you: a PagingSource<Int, …> over offsets still duplicates and skips as in the simulation. The docs treat the data source as immutable (fixed once created): when the underlying data changes, call invalidate(), and the Pager creates a new PagingSource and reloads from the key getRefreshKey() returns. [[src:ax-paging]]')
    B(C, S_, 3, 'p', 'Khi cần chạy được lúc mất mạng: RemoteMediator (thành phần của Paging nối mạng với database) tải từ mạng mỗi khi hết dữ liệu đã cache và ghi vào Room (database của Android); database là nguồn sự thật, UI chỉ hiện những gì đã nằm trong database. Nếu khóa của server không gắn với từng mục, như next_page_token, tài liệu lưu nó trong một bảng remote_keys riêng, ghi trong cùng một giao dịch (thao tác trọn gói) với dữ liệu. initialize() chọn bỏ qua hay chạy lần làm mới đầu tiên. [[src:ax-paging-db]]',
      'When it must work offline: a RemoteMediator (the Paging component that links the network to the database) loads from the network whenever cached data runs out and writes it to Room (Android\'s database); the database is the source of truth, and the UI shows only what is already in it. If the server key is not tied to individual items, such as a next_page_token, the docs keep it in a separate remote_keys table, written in the same transaction (an all-or-nothing operation) as the data. initialize() chooses whether to skip or launch the first refresh. [[src:ax-paging-db]]')
    B(C, S_, 4, 'note', 'Đặt key cho mục: items(posts.itemCount, key = posts.itemKey { it.id }). Key giúp giữ trạng thái mục khi danh sách đổi [[src:cp-lists]], nhưng cũng biến bài lặp của offset thành crash: SubcomposeLayout ném lỗi khi một key được dùng lần hai (commit 3fa4054). [[src:ax-subcompose-src]]',
      'Give items keys: items(posts.itemCount, key = posts.itemKey { it.id }). Keys keep item state across list changes [[src:cp-lists]], but they also turn an offset duplicate into a crash: SubcomposeLayout throws when a key is used twice (commit 3fa4054). [[src:ax-subcompose-src]]')
    B(C, S_, 4, 'kind', 'android')

    S_ = 'bugs'
    a(C + '.sec.%s.title' % S_, 'Ba lỗi hay gặp', 'Three common bugs')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'bug', 'Crash "Key … was already used" chỉ xảy ra với vài người, lúc giờ cao điểm đăng bài.', 'A "Key … was already used" crash hits only some users, at peak publishing hours.')
    B(C, S_, 1, 'cause', 'Phân trang offset; có bài mới chèn lên đầu giữa hai lần tải trang, trang sau trả lại bài đã có, và LazyColumn dùng id làm key.', 'Offset paging; new posts are inserted at the top between two page loads, the next page repeats a post already shown, and LazyColumn uses the id as key.')
    B(C, S_, 1, 'fix', 'Chuyển sang cursor (page_token). Lọc trùng id ở app chỉ che được lỗi lặp; lỗi bỏ sót khi có bài bị gỡ vẫn còn.', 'Move to a cursor (page_token). Filtering duplicate ids in the app only hides duplicates; skips from removed posts remain.')
    B(C, S_, 2, 'bug', 'Danh sách dừng tải giữa chừng dù server còn bài.', 'The list stops loading halfway although the server has more posts.')
    B(C, S_, 2, 'cause', 'App coi trang ít hơn page_size là trang cuối. Server được phép trả trang ngắn, kể cả rỗng, khi chưa hết (ví dụ sau khi lọc bài bị ẩn).', 'The app treats a page shorter than page_size as the last. The server may return short pages, even empty ones, before the end (for example after filtering hidden posts).')
    B(C, S_, 2, 'fix', 'Chỉ dừng khi next_page_token rỗng, đúng như AIP-158; trong PagingSource là nextKey = null đúng lúc đó. [[src:aip-158]]', 'Stop only when next_page_token is empty, as AIP-158 says; in a PagingSource that is nextKey = null at exactly that point. [[src:aip-158]]')
    B(C, S_, 3, 'bug', 'Sau một bản cập nhật backend, trang 2 của mọi người dùng bản app cũ đều lỗi.', 'After a backend release, page 2 fails for everyone on the old app version.')
    B(C, S_, 3, 'cause', 'App giải token (Base64 của {"offset":20}) để tự tạo token cho trang kế; backend đổi định dạng token.', 'The app decoded the token (Base64 of {"offset":20}) to build the next one itself; the backend changed the token format.')
    B(C, S_, 3, 'fix', 'Không bao giờ đọc hay tự tạo token; chỉ gửi lại next_page_token nhận được. Phía server, token phải thật sự mờ để không ai làm vậy được. [[src:aip-158]]', 'Never read or build tokens; only send back the next_page_token received. On the server side, tokens must be truly opaque so nobody can. [[src:aip-158]]')

    S_ = 'ex'
    a(C + '.sec.%s.title' % S_, 'Bài tập', 'Exercise')
    a(C + '.sec.%s.badge' % S_, 'guideline')
    B(C, S_, 1, 'ex', 'Chọn cách phân trang, khóa sắp xếp và khóa phân xử (khóa phụ quyết định khi hai mục trùng khóa chính) cho: (a) lịch sử khám của người dùng, mới nhất trước, có thể bị xóa; (b) danh sách bác sĩ theo tên A→Z, quản trị viên có thể thêm bác sĩ bất kỳ lúc nào. Rồi tính: feed dùng offset, 20 bài một trang; trong lúc người dùng đọc trang 1 có 5 bài mới được đăng. Đầu trang 2 có bao nhiêu bài lặp? Nếu thay vào đó gỡ 2 bài trong trang 1 thì bao nhiêu bài bị bỏ sót?',
      'Choose the paging approach, sort key and tie-breaker (a secondary key that decides between items sharing the main key) for: (a) the user\'s visit history, newest first, entries may be deleted; (b) the doctor list by name A→Z, where admins may add a doctor at any time. Then compute: a feed with offset paging, 20 posts per page; while the user reads page 1, 5 new posts are published. How many duplicates start page 2? If instead 2 posts of page 1 were removed, how many posts are skipped?')
    B(C, S_, 1, 'hint', 'Danh sách nào đổi trong lúc người dùng đang cuộn? Hai mục có thể trùng khóa sắp xếp không?', 'Which list changes while the user scrolls? Can two items share a sort key?')
    B(C, S_, 1, 'sol', '(a) Cursor theo (thời gian khám, id): mục bị xóa không làm lệch trang sau. (b) Cursor theo (tên, id), vì hai bác sĩ có thể trùng tên; bác sĩ mới có tên đứng trước chỗ đang xem chỉ hiện sau khi làm mới, còn với offset thì gây một mục lặp. Phép tính: 5 bài lặp (5 bài cuối của trang 1, ở vị trí 16 tới 20, hiện lại); gỡ 2 bài thì 2 bài bị bỏ sót.',
      '(a) A cursor on (visit time, id): deleted entries do not shift later pages. (b) A cursor on (name, id), since two doctors can share a name; a new doctor whose name sorts before the current spot only shows after a refresh, while offset would produce a duplicate. The arithmetic: 5 duplicates (the last 5 posts of page 1, at positions 16 to 20, show again); with 2 posts removed, 2 posts are skipped.')

    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Phân trang offset, có 2 bài mới chèn lên đầu giữa trang 1 và trang 2. Chuyện gì xảy ra?', 'Offset paging, 2 posts inserted at the top between page 1 and page 2. What happens?', 'Hai bài cuối của trang 1 hiện lại ở đầu trang 2.', 'The last two posts of page 1 show again at the top of page 2.', 'Mọi vị trí bị đẩy xuống hai.', 'Every position moves down by two.'),
        ('q2', 'Vì sao lỗi bỏ sót của offset khó phát hiện hơn lỗi lặp?', 'Why is an offset skip harder to notice than a duplicate?', 'Mục bị bỏ sót không bao giờ tới app, nên không có gì hiện sai và không lọc được.', 'The skipped item never reaches the app, so nothing looks wrong and nothing can be filtered.', 'Lọc trùng id chỉ chữa được lỗi lặp.', 'Filtering duplicate ids only fixes duplicates.'),
        ('q3', 'Server trả một trang 7 mục dù page_size là 20. Đã hết danh sách chưa?', 'The server returns 7 items although page_size is 20. Is the list finished?', 'Chưa chắc. Theo AIP-158, chỉ next_page_token rỗng mới nghĩa là hết.', 'Not necessarily. Per AIP-158, only an empty next_page_token means the end.', 'Trang ngắn, kể cả rỗng, vẫn hợp lệ.', 'Short pages, even empty ones, are valid.'),
        ('q4', 'Dùng cursor rồi, khi nào người dùng mới thấy bài vừa đăng ở đầu?', 'With a cursor, when does the user see a post just published at the top?', 'Sau khi làm mới (kéo để làm mới, hay invalidate rồi tải lại từ đầu).', 'After a refresh (pull to refresh, or invalidate and reload from the top).', 'Cursor giữ trang sau đúng, không tự kéo bài mới vào.', 'A cursor keeps later pages right; it does not pull new posts in.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
